###### Motivation for this change
Update nginx http3 configuration.
Fixed work nginx with enabled  http3 protocol on multiple hosts.
Option `reuseport` only needs to be specified once on one of the hosts.

Test configuration:
```
  services.nginx = {
    enable = true;
    enableReload = true;
    package = pkgs.nginxQuic;
    user = "nginx";
    group = "nginx";

    virtualHosts."default_server" = {
      default = true;
      addSSL = true;
      forceSSL = false;
      enableACME = false;
      http3 = true;
      sslCertificate    = "/var/certs/test1.crt";
      sslCertificateKey = "/var/certs/test1.key";
    };

    virtualHosts."test1.local" = {
      default = false;
      addSSL = true;
      forceSSL = false;
      enableACME = false;
      http3 = true;
      reuseport = true;
      sslCertificate    = "/var/certs/test1.crt";
      sslCertificateKey = "/var/certs/test1.key";
      root = "/var/www/test1";
    };

    virtualHosts."test2.local" = {
      default = false;
      addSSL = true;
      forceSSL = false;
      enableACME = false;
      http3 = false;
      sslCertificate    = "/var/certs/test1.crt";
      sslCertificateKey = "/var/certs/test1.key";
      root = "/var/www/test2";
    };
  };
```
